extension IMService.V1 {
    /// `image` resource.
    public struct Image: Sendable {
        public let client: LarkClient
        public init(client: LarkClient) { self.client = client }

        /// 下载图片
        ///
        /// 通过已上传图片的 Key 值下载图片。
        ///
        /// ## 前提条件
        ///
        /// 应用需要开启[机器人能力](https://open.feishu.cn/document/uAjLw4CM/ugTN1YjL4UTN24CO1UjN/trouble-shooting/how-to-enable-bot-ability)。
        ///
        /// ## 使用限制
        ///
        /// - 只能下载由当前机器人上传的图片，且上传时图片类型为 **用于发送消息**。**用于设置头像** 的图片暂不支持下载。
        /// - 该接口仅适用于通过图片的 Key 下载图片。如果你需要下载用户发送消息内的资源文件，可使用[获取消息中的资源文件](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message-resource/get)接口。
        ///
        /// - SeeAlso: <https://open.feishu.cn/api-explorer?from=op_doc_tab&apiName=get&project=im&resource=image&version=v1>
        ///
        /// `GET /open-apis/im/v1/images/:image_key`
        public func get(imageKey: String, options: RequestOptions = .none) async throws -> LarkBinaryResponse {
            try await client.download(.get, "/open-apis/im/v1/images/\(LarkURL.escapePathSegment(imageKey))", query: nil, body: .none, options: options)
        }

        /// 上传图片
        ///
        /// 调用本接口将图片上传至飞书开放平台，支持上传 JPG、JPEG、PNG、WEBP、GIF、BMP、ICO、TIFF、HEIC 格式的图片，但需要注意 TIFF、HEIC 上传后会被转为 JPG 格式。
        ///
        /// ## 使用场景
        ///
        /// 如果需要发送图片消息，或者将图片作为头像，则需要先调用本接口将图片上传至开放平台，平台会返回一个图片标识（image_key），后续使用该 Key 值调用其他 API。例如：
        ///
        /// - [发送消息](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message/create)时，如果需要发送图片，则需要先调用本接口上传图片（上传时图片类型需要选择 **用于发送消息**），并使用返回结果中的 image_key 发送图片消息。
        /// - [创建用户](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/contact-v3/user/create)时，如果需要设置用户头像，则需要先调用本接口将头像上传（上传时图片类型需要选择 **用于设置头像**），并使用返回结果中的 image_key 设置头像。
        ///
        /// ## 前提条件
        ///
        /// 应用需要开启[机器人能力](https://open.feishu.cn/document/uAjLw4CM/ugTN1YjL4UTN24CO1UjN/trouble-shooting/how-to-enable-bot-ability)。
        ///
        /// ## 使用限制
        ///
        /// - 上传的图片大小不能超过 10 MB，且不支持上传大小为 0 的图片。
        /// - 上传图片的分辨率限制：;	- GIF 图片分辨率不能超过 2000 x 2000，其他图片分辨率不能超过 12000 x 12000。
        /// 	- 用于设置头像的图片分辨率不能超过 4096 x 4096。
        ///
        /// 如需上传高分辨率图片，可使用[上传文件](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/file/create)接口，将图片作为文件进行上传。注意该方式不支持将图片文件设置为头像。
        ///
        /// - SeeAlso: <https://open.feishu.cn/api-explorer?from=op_doc_tab&apiName=create&project=im&resource=image&version=v1>
        ///
        /// `POST /open-apis/im/v1/images`
        public func create(body: LarkIM.IM.ImageCreateBody, options: RequestOptions = .none) async throws -> LarkResponse<LarkIM.IM.ImageCreateResponse> {
            try await client.request(.post, "/open-apis/im/v1/images", query: nil, body: .multipart(body.multipartForm()), options: options)
        }

    }
}

